-- Sample database: SaaS Analytics (advanced)
-- GENERATED by app/sample_dbs/generate.py — do not edit by hand

CREATE TABLE plans (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name           varchar(40) NOT NULL UNIQUE,
  monthly_price  numeric(10,2) NOT NULL CHECK (monthly_price >= 0),
  seats_included integer NOT NULL,
  is_active      boolean NOT NULL DEFAULT true
);
CREATE TABLE companies (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        varchar(120) NOT NULL,
  industry    varchar(40),
  country     varchar(40) NOT NULL,
  employees   integer,
  created_at  date NOT NULL
);
CREATE TABLE users (
  id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company_id    integer NOT NULL REFERENCES companies(id),
  email         varchar(160) NOT NULL UNIQUE,
  full_name     varchar(100) NOT NULL,
  role          varchar(10) NOT NULL CHECK (role IN ('owner','admin','member')),
  signed_up_at  timestamp NOT NULL,
  last_seen_at  timestamp
);
CREATE TABLE subscriptions (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company_id  integer NOT NULL REFERENCES companies(id),
  plan_id     integer NOT NULL REFERENCES plans(id),
  status      varchar(10) NOT NULL CHECK (status IN ('trial','active','canceled')),
  started_at  date NOT NULL,
  ended_at    date,
  mrr         numeric(10,2) NOT NULL,
  CHECK (ended_at IS NULL OR ended_at >= started_at)
);
CREATE TABLE invoices (
  id               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company_id       integer NOT NULL REFERENCES companies(id),
  subscription_id  integer NOT NULL REFERENCES subscriptions(id),
  period_start     date NOT NULL,
  amount           numeric(10,2) NOT NULL,
  status           varchar(10) NOT NULL CHECK (status IN ('paid','open','overdue','void')),
  paid_at          date
);
CREATE TABLE events (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id      integer NOT NULL REFERENCES users(id),
  event_type   varchar(30) NOT NULL,
  occurred_at  timestamp NOT NULL,
  properties   jsonb NOT NULL DEFAULT '{}'
);
CREATE INDEX idx_users_company ON users(company_id);
CREATE INDEX idx_subs_company ON subscriptions(company_id);
CREATE INDEX idx_invoices_company ON invoices(company_id);
CREATE INDEX idx_events_user_time ON events(user_id, occurred_at);
CREATE INDEX idx_events_type_time ON events(event_type, occurred_at);

COMMENT ON TABLE plans IS 'แพ็กเกจราคา (Legacy ปิดขายแล้วแต่ยังมีลูกค้าเดิมใช้)';
COMMENT ON TABLE companies IS 'บริษัทลูกค้า (tenant) — บางรายยังอยู่ช่วง trial หรือยกเลิกแล้ว';
COMMENT ON COLUMN companies.industry IS 'อุตสาหกรรม (อาจเป็น NULL)';
COMMENT ON TABLE users IS 'ผู้ใช้ของแต่ละบริษัท — last_seen_at เป็น NULL ถ้าไม่เคยใช้งานหลังสมัคร';
COMMENT ON TABLE subscriptions IS 'ประวัติการสมัคร — 1 บริษัทมีหลายแถวเมื่ออัปเกรด/ดาวน์เกรด; ended_at IS NULL = ยังใช้งานอยู่; status trial + ended_at = ช่วงทดลองที่จบแล้ว';
COMMENT ON COLUMN subscriptions.mrr IS 'Monthly Recurring Revenue ของ subscription นี้ (trial = 0)';
COMMENT ON TABLE invoices IS 'ใบแจ้งหนี้รายเดือน — status overdue/open = ยังไม่ได้รับเงิน';
COMMENT ON TABLE events IS 'event stream การใช้งานผลิตภัณฑ์ — properties เป็น JSONB (คีย์ไม่เหมือนกันทุก event)';
COMMENT ON COLUMN events.properties IS 'เช่น {"device": "web", "duration_ms": 1200, "report_type": "sales"}';







































































































